    section1Body1: 'Редовната физическа активност влияе на много от системите на тялото, включително на тези, участващи в хормоналната регулация и функционирането на менструалния цикъл. Тя действа по-специално върху чувствителността към инсулин, управлението на стреса и качеството на съня — три фактора, които взаимодействат с хормоналния баланс.',
