    neutral1Text: 'මෙම ප්‍රතිලාභ ක්‍රමයෙන් ගොඩනැගේ: මෙය එක් සැසියකින් පසු ක්ෂණික බලපෑමක් නොවේ.',
    section3Intro: 'කිසිදු ක්‍රියාකාරකමක් වෙනත් එකකට වඩා “හොඳ” නැත: වඩාත්ම සඵල එක නම් ඔබ නිතිපතා කිරීමට කැමති එකයි.',
