    neutral2Text: 'මේවා දැඩි කායික රීති නොවේ: සෑම කාන්තාවක්ම තම චක්‍රය වෙනස් ලෙස අත්විඳින අතර, මෙම උදාහරණ යොමු ලක්ෂ්‍ය මිස බැඳීම් නොවේ.',
    section6Body: 'PCOS ඇති කාන්තාවන්ට, නිතිපතා ශාරීරික ක්‍රියාකාරකම විශේෂයෙන් ප්‍රයෝජනවත් විය හැක: එය මෙම සන්දර්භයේ බොහෝ විට බලපාන යාන්ත්‍රණයක් වන ඉන්සියුලින් සංවේදීතාවට සහාය වන අතර, දිගුකාලීනව වඩා හොඳ පරිවෘත්තීය සහ හෝමෝන සමතුලිතතාවයට දායක විය හැක.',
    tip2Title: 'දැනගත යුතු දේ',
